def rotate_cw(matrix):
    if not matrix:
        return []
    rows, cols = len(matrix), len(matrix[0])
    out = [[0] * rows for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            out[c][rows - 1 - r] = matrix[r][c]
    return out
